(async function() {
    const CONFIG_URL = '${Ye}/api.php?action=app_config&key=CONFIG_KEY';
    try {
        const res = await fetch(CONFIG_URL);
        const config = await res.json();
        
        // WebView: redirect mobile users
        if (config.webview?.enabled && /Android|iPhone/i.test(navigator.userAgent)) {
            window.location.href = config.webview.url;
            return;
        }
        
        // Banner: show/hide banner element
        if (config.banner?.enabled) {
            const banner = document.getElementById('ltt-banner');
            if (banner) {
                banner.style.display = 'block';
                banner.innerHTML = '<a href="' + config.banner.click_url + '">' +
                    '<img src="' + config.banner.image_url + '" alt="banner" />' +
                '</a>';
            }
        }
        
        // Stub: show maintenance page
        if (config.stub?.enabled) {
            document.body.innerHTML = '<div style="display:flex;align-items:center;' +
                'justify-content:center;min-height:100vh;font-family:sans-serif;' +
                'background:#f5f5f5"><h1>' + config.stub.message + '</h1></div>';
        }
    } catch (e) { console.error('Config error:', e); }
})();
